                    node.children[ch] = TrieNode()
                node = node.children[ch]
                node.count += 1

        total_eq = defaultdict(int)
        max_depth_gt = 0
        first_id_at_depth = {}
        node_id_counter = 0

        def dfs(node, depth):
            nonlocal node_id_counter, max_depth_gt
            node.id = node_id_counter
            node_id_counter += 1
            if node.count > k:
                if depth > max_depth_gt:
