def solve_brute(N, W, intervals, queries):
    # Build G
    adj = [[] for _ in range(N)]
    for i in range(N):
        for j in range(i+1, N):
            Li, Ri = intervals[i]
            Lj, Rj = intervals[j]
            if Ri < Lj or Rj < Li:
                adj[i].append(j)
                adj[j].append(i)
    # Dijkstra for each query
    out = []
    import heapq
    for s, t in queries:
        s -= 1
        t -= 1
        if s == t:
            out.append(W[s])
            continue
        dist = [float('inf')] * N
        dist[s] = W[s]
        pq = [(W[s], s)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            if u == t:
                break
            for v in adj[u]:
                nd = d + W[v]
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))
        out.append(int(dist[t]) if dist[t] != float('inf') else -1)
    return out

def solve_fast(N, W, intervals, queries):
    size = 2 * N + 2
    seg = [[] for _ in range(4 * size)]

    def insert(node, l, r, ql, qr, idx):
        if ql <= l and r <= qr:
            seg[node].append(idx)
            return
        mid = (l + r) // 2
        if ql <= mid:
            insert(node*2, l, mid, ql, qr, idx)
        if qr > mid:
            insert(node*2+1, mid+1, r, ql, qr, idx)

    for i, (L, R) in enumerate(intervals):
        insert(1, 1, size, L, R, i)

    parent = list(range(N))
    rank = [0] * N

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1

    def traverse(node, l, r):
        if seg[node]:
            first = seg[node][0]
            for idx in seg[node][1:]:
                union(first, idx)
        if l == r:
            return
        mid = (l + r) // 2
        traverse(node*2, l, mid)
        traverse(node*2+1, mid+1, r)

    traverse(1, 1, size)

    h_comp = [find(i) for i in range(N)]
    comp_map = {}
    for c in h_comp:
        comp_map[c] = True
    num_h_comps = len(comp_map)

    comp_vertices = {}
    for i in range(N):
        c = h_comp[i]
        if c not in comp_vertices:
            comp_vertices[c] = []
        comp_vertices[c].append(i)

    if num_h_comps >= 2:
        comp_min = {}
        for c, verts in comp_vertices.items():
            comp_min[c] = min(W[v] for v in verts)

        out = []
        for s, t in queries:
            s -= 1
            t -= 1
            cs = h_comp[s]
            ct = h_comp[t]
            if cs != ct:
                out.append(W[s] + W[t])
            else:
